// Adapted from master2 apps/api/src/modules/payments.service.ts:34-131 @ 01f83c0
// (Prisma replaced by an injected client; zod schema reduced to the checks the flow
// needs; hashRequestPayload/stableStringify from packages/domain/src/idempotency.ts
// and the audit/outbox helpers inlined; fakeClient() is test scaffolding that records
// every write, mirroring the vi.fn() tx in payments.service.test.ts).
import { createHash } from 'node:crypto';

export class HttpError extends Error {
  constructor(status, code, message) {
    super(message);
    this.status = status;
    this.code = code;
  }
}

function stableStringify(value) {
  if (Array.isArray(value)) return `[${value.map(stableStringify).join(',')}]`;
  if (value && typeof value === 'object') {
    return `{${Object.keys(value).sort().map((k) => `${JSON.stringify(k)}:${stableStringify(value[k])}`).join(',')}}`;
  }
  return JSON.stringify(value);
}

export const hashRequestPayload = (payload) => createHash('sha256').update(stableStringify(payload)).digest('hex');

const canTransitionInvoice = (from, to) => to === 'paid' && ['open', 'uncollectible'].includes(from);

function parseMockWebhook(input) {
  const ok = input && typeof input.providerEventId === 'string' && input.providerEventId.trim().length >= 4
    && ['payment.succeeded', 'payment.failed'].includes(input.eventType) && typeof input.paymentId === 'string';
  if (!ok) throw new HttpError(400, 'webhook.invalid', 'The mock webhook body is invalid.');
  return { ...input, providerEventId: input.providerEventId.trim() };
}

export async function processMockPaymentWebhook(prisma, tenant, input) {
  if (!tenant.permissions.includes('payments:manage')) {
    throw new HttpError(403, 'permission.denied', 'Missing permission payments:manage.');
  }
  const body = parseMockWebhook(input);
  const payloadHash = hashRequestPayload(body);

  return prisma.$transaction(async (tx) => {
    const existing = await tx.webhookEvent.findUnique({ where: { providerEventId: body.providerEventId } });
    if (existing) {
      if (existing.organizationId !== tenant.organizationId || hashRequestPayload(existing.payload) !== payloadHash) {
        throw new HttpError(409, 'webhook.identity_conflict', 'Provider event belongs to another tenant or payload.');
      }

      if (existing.processedAt) {
        return { duplicate: true, eventId: existing.id };
      }
    }

    const payment = await tx.payment.findFirst({ where: { id: body.paymentId, organizationId: tenant.organizationId } });
    if (!payment) {
      throw new HttpError(404, 'payment.not_found', 'Payment was not found in this organization.');
    }

    const invoice = await tx.invoice.findFirst({ where: { id: payment.invoiceId, organizationId: tenant.organizationId } });
    if (!invoice) {
      throw new HttpError(404, 'invoice.not_found', 'Invoice was not found in this organization.');
    }

    if (body.eventType === 'payment.succeeded' && invoice.status !== 'paid' && !canTransitionInvoice(invoice.status, 'paid')) {
      throw new HttpError(409, 'invoice.transition_invalid', 'Invoice cannot transition to paid from its current state.');
    }

    const event = existing ?? await tx.webhookEvent.create({ data: { organizationId: tenant.organizationId, providerEventId: body.providerEventId, payload: body } });

    const succeeded = body.eventType === 'payment.succeeded';
    const alreadySucceeded = payment.status === 'succeeded';
    if (!alreadySucceeded) {
      await tx.payment.update({ where: { id: payment.id }, data: { status: succeeded ? 'succeeded' : 'failed' } });
      if (succeeded && invoice.status !== 'paid') {
        await tx.invoice.update({ where: { id: invoice.id }, data: { status: 'paid' } });
      }
    }

    await tx.webhookEvent.update({ where: { id: event.id }, data: { processedAt: new Date() } });
    await tx.auditLog.create({ data: { action: alreadySucceeded && !succeeded ? 'payment.failed.ignored' : body.eventType, entityId: payment.id } });
    if (!(alreadySucceeded && !succeeded)) {
      await tx.outboxEvent.create({ data: { topic: body.eventType, payload: { paymentId: payment.id, invoiceId: payment.invoiceId } } });
    }

    return { processed: true, eventId: event.id, ignoredFailure: alreadySucceeded && !succeeded };
  });
}

/** test scaffolding: a client whose reads return the given rows and whose writes are recorded */
export function fakeClient({ event = null, payment = null, invoice = null } = {}) {
  const writes = [];
  const rec = (name, ret) => async (args) => {
    writes.push({ name, args });
    return ret ?? { id: `${name}-1`, ...(args?.data ?? {}) };
  };
  const tx = {
    webhookEvent: { findUnique: async () => event, create: rec('webhookEvent.create'), update: rec('webhookEvent.update') },
    payment: { findFirst: async () => payment, update: rec('payment.update') },
    invoice: { findFirst: async () => invoice, update: rec('invoice.update') },
    auditLog: { create: rec('auditLog.create') },
    outboxEvent: { create: rec('outboxEvent.create') },
  };
  return { writes, $transaction: (fn) => fn(tx) };
}

